market=dict(summary='Tanzania has separate mainland TLSB public/national services, a Zanzibar public library board, public/private university networks and specialized institutional libraries. Koha is the strongest evidenced adapter opportunity, but network reach is not the same as an open searchable catalog. Five independent institutions/networks returned specific books in this bounded test; four used Koha and one a custom ZLSB OPAC. This feasibility sample is not national LMS market share.',platform_strategy='Prioritize a policy-aware Koha adapter for SNAL, SUZA, MUST and DarTU; preserve direct detail redirects and reference-only locations. ZLSB needs a custom result/modal parser with catalog-listed status only. Keep TLSB iNDLS as the largest public-network opportunity pending a documented anonymous interface. COTUL is a coordination and resource-licensing route, not a verified national physical-book union endpoint.',adoption_evidence=[dict(claim='2019 dissertation purposively studied Koha-implementing OUT, IFM and CBE libraries in Dar es Salaam; supports local adoption, not prevalence.',scope='Three purposively sampled academic libraries',date='2019',source_url='https://libraryrepository.udsm.ac.tz/bitstreams/07f1b039-2656-4b06-9530-359ce03d9539/download',evidence_path='evidence/discovery6.json'),dict(claim='Current official Ardhi library page explicitly identifies Koha.',scope='One institution',date='undated',source_url='https://aru.ac.tz/campuslives/library',evidence_path='evidence/discovery2.json'),dict(claim='Four successful current catalog endpoints identify Koha; ZLSB is custom. Historical ABCD reports for Sokoine/Mzumbe should not override observed current Koha branding.',scope='This access-selected screen only',date='2026-11-15',source_url='http://www.snal.sua.ac.tz/',evidence_path='evidence/sua-home.html'),dict(claim='Makumira official page identifies Mandarin Oasis and 150,000 entered records; live endpoint identifies Mandarin 5.7.11 but startup fails.',scope='One institution',date='2026-11-15',source_url='https://makumira.ac.tz/library.php',evidence_path='evidence/tumaweb-home.html')],network_opportunities=[dict(name='TLSB iNDLS',scope='Mainland national/public network;43 libraries total,11 currently on iNDLS in October 2026 statement',source_url='https://www.tlsb.go.tz/news/tlsb-board-chairperson-commends-management-on-indls-development-directs-expansion-of-services-to-all-43-libraries-nationwide',verification='Official dated 15 October 2026 page saved; no anonymous physical-book result verified.',integration_implication='One lawful shared public interface could have substantial reach, but do not claim43 searchable libraries or count branches separately.'),dict(name='Consortium of Tanzania Universities and Research Libraries (COTUL)',scope='University, college/polytechnic, research and special libraries',source_url='https://www.eifl.info/country/tanzania',verification='EIFL country page lists 96 members and separately says 47 institutions in its work; these denominators differ. Source indexed in discovery3.',integration_implication='Useful coordination/training/resource-licensing network; no tested shared physical-book catalog, and licensed journals/ebooks are distinct from local physical holdings.'),dict(name='Zanzibar Library Services Board',scope='One five-branch public network',source_url='https://zlms.zls.go.tz/online-services/',verification='Actual Uchu query returned title and In Collection status, without branch/copy availability.',integration_implication='One custom adapter could serve this public network; branch-level coverage and conflicting title totals need validation.')])
